"% model.m
% Trim a transport aircraft in a steady climbing coordinated turn.
% Solves 3 coupled nonlinear equations using Newton-Raphson iteration.

% --- 1. Define Constants ---
W = 230000.0;      % lbf
S = 2400.0;        % ft^2
h = 31000.0;       % ft
V = 730.0;         % ft/s
gamma_deg = 3.0;   % deg
phi_deg = 30.0;    % deg

CL0 = 0.15;
CLa = 5.2;         % /rad
CLde = 0.35;       % /rad

CD0 = 0.021;
k = 0.043;

rho0 = 0.0023769;  % slug/ft^3
h_scale = 23800.0; % ft

iT_deg = 2.5;      % deg
zT = 2.0;          % ft

Cm0 = 0.02;
Cma = -0.3;        % /rad
Cmde = -0.85;      % /rad
cbar = 17.0;       % ft

% --- 2. Derived Quantities ---
% Convert angles to radians for calculation
gamma = deg2rad(gamma_deg);
phi = deg2rad(phi_deg);
iT = deg2rad(iT_deg);

% Atmosphere
rho = rho0 * exp(-h / h_scale);
q = 0.5 * rho * V^2;

% Load Factor (analytical)
load_factor = cos(gamma) / cos(phi);

% --- 3. Newton-Raphson Solver ---
% Unknowns: x(1) = alpha (rad), x(2) = T (lbf), x(3) = delta_e (rad)

% Initial Guess
% Alpha: ~2 deg, Thrust: ~25000 lbf (estimated from drag), Elevator: ~0 deg
x = [deg2rad(2.0); 25000.0; 0.0]; 

% Tolerances
tol = 1e-8;
max_iter = 50;

for iter = 1:max_iter
    alpha = x(1);
    T = x(2);
    de = x(3);

    % Aerodynamic Coefficients
    CL = CL0 + CLa * alpha + CLde * de;
    CD = CD0 + k * CL^2;

    % --- Residuals F(x) ---
    % Eq 1: Vertical Force Balance
    % q*S*CL*cos(phi) + T*sin(alpha + iT) - W*cos(gamma) = 0
    f1 = q * S * CL * cos(phi) + T * sin(alpha + iT) - W * cos(gamma);

    % Eq 2: Flight Path Force Balance
    % T*cos(alpha + iT) - q*S*CD - W*sin(gamma) = 0
    f2 = T * cos(alpha + iT) - q * S * CD - W * sin(gamma);

    % Eq 3: Pitching Moment Balance
    % q*S*cbar*(Cm0 + Cma*alpha + Cmde*de) + T*sin(iT)*zT = 0
    f3 = q * S * cbar * (Cm0 + Cma * alpha + Cmde * de) + T * sin(iT) * zT;

    F = [f1; f2; f3];

    % Check convergence
    if norm(F) < tol
        break;
    end

    % --- Jacobian J(x) ---
    % Derivatives of CL
    dCL_da = CLa;
    dCL_dT = 0;
    dCL_dde = CLde;

    % Derivatives of CD
    dCD_da = 2 * k * CL * dCL_da;
    dCD_dT = 0;
    dCD_dde = 2 * k * CL * dCL_dde;

    % Row 1 (Vertical Eq)
    J11 = q * S * cos(phi) * dCL_da + T * cos(alpha + iT);
    J12 = sin(alpha + iT);
    J13 = q * S * cos(phi) * dCL_dde;

    % Row 2 (Path Eq)
    J21 = -T * sin(alpha + iT) - q * S * dCD_da;
    J22 = cos(alpha + iT);
    J23 = -q * S * dCD_dde;

    % Row 3 (Moment Eq)
    J31 = q * S * cbar * Cma;
    J32 = sin(iT) * zT;
    J33 = q * S * cbar * Cmde;

    J = [J11, J12, J13;
         J21, J22, J23;
         J31, J32, J33];

    % Newton Step
    dx = J \ (-F);
    x = x + dx;
end

% --- 4. Prepare Results ---
alpha_trim_deg = rad2deg(x(1));
thrust_lbf = x(2);
delta_e_trim_deg = rad2deg(x(3));

% Create struct for JSON output
resultStruct.alpha_trim_deg = alpha_trim_deg;
resultStruct.thrust_lbf = thrust_lbf;
resultStruct.delta_e_trim_deg = delta_e_trim_deg;
resultStruct.load_factor = load_factor;

% --- 5. Write JSON ---
jsonStr = jsonencode(resultStruct);
fid = fopen('result.json', 'w');
fwrite(fid, jsonStr);
fclose(fid);"
